INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$3595a991$SATQ$, $SATQ$bf69cb89-2c0b-45b8-b5bc-df6d238c3f33$SATQ$::uuid, $SATQ$cd6b4a0f-0a13-4c13-b2af-ab000e5e5777$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In 1930, Japanese American artist Chiura Obata depicted the natural beauty of Yosemite National Park in two memorable woodcuts: <em>Evening at Carl Inn </em>and <em>Lake Basin in the High Sierra</em>. In 2019, <span aria-hidden="true">______</span><span class="sr-only">blank</span> exhibited alongside 150 of Obata&rsquo;s other works in a single-artist show at the Smithsonian American Art Museum.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"59070ee6-c2cc-4f25-aafb-7ccbcf1b2c89","content":"<p>it was</p>"},{"id":"8497c915-57e8-4664-9f9b-da7577eb5ead","content":"<p>they were</p>"},{"id":"bd0073d9-1e43-4575-90ee-a2e03945a0f9","content":"<p>this was</p>"},{"id":"05de797b-5951-4445-835d-b92ac1d8ff23","content":"<p>some were</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["8497c915-57e8-4664-9f9b-da7577eb5ead"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is pronoun&ndash;antecedent agreement. The plural pronoun &ldquo;they&rdquo; agrees in number with the plural antecedent &ldquo;woodcuts&rdquo; and clearly identifies what was exhibited at the Smithsonian American Art Museum. </p><p>Choice A is incorrect because the singular pronoun &ldquo;it&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;woodcuts.&rdquo; Choice C is incorrect because the singular pronoun &ldquo;this&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;woodcuts.&rdquo; Choice D is incorrect because the plural pronoun &ldquo;some&rdquo; is illogical in this context (referring to &ldquo;some&rdquo; of two woodcuts). </p>$SATQ$, false, 0, $SATQ$OSP-637-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$93d853aa-332b-4110-a0ca-75c0f589df3f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3595a991","external_id":"bf69cb89-2c0b-45b8-b5bc-df6d238c3f33","vaultid":"cd6b4a0f-0a13-4c13-b2af-ab000e5e5777","uId":"b7a39dcd-e49e-492f-92d8-e313c351fdbb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In 1930, Japanese American artist Chiura Obata depicted the natural beauty of Yosemite National Park in two memorable woodcuts: <em>Evening at Carl Inn </em>and <em>Lake Basin in the High Sierra</em>. In 2019, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> exhibited alongside 150 of Obata&rsquo;s other works in a single-artist show at the Smithsonian American Art Museum.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"59070ee6-c2cc-4f25-aafb-7ccbcf1b2c89","content":"<p>it was</p>"},{"id":"8497c915-57e8-4664-9f9b-da7577eb5ead","content":"<p>they were</p>"},{"id":"bd0073d9-1e43-4575-90ee-a2e03945a0f9","content":"<p>this was</p>"},{"id":"05de797b-5951-4445-835d-b92ac1d8ff23","content":"<p>some were</p>"}],"keys":["8497c915-57e8-4664-9f9b-da7577eb5ead"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is pronoun&ndash;antecedent agreement. The plural pronoun &ldquo;they&rdquo; agrees in number with the plural antecedent &ldquo;woodcuts&rdquo; and clearly identifies what was exhibited at the Smithsonian American Art Museum. </p><p>Choice A is incorrect because the singular pronoun &ldquo;it&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;woodcuts.&rdquo; Choice C is incorrect because the singular pronoun &ldquo;this&rdquo; doesn&rsquo;t agree in number with the plural antecedent &ldquo;woodcuts.&rdquo; Choice D is incorrect because the plural pronoun &ldquo;some&rdquo; is illogical in this context (referring to &ldquo;some&rdquo; of two woodcuts). </p>","parenttemplatename":"OSP-637-SEC","parenttemplateid":"","templateclusterid":"93d853aa-332b-4110-a0ca-75c0f589df3f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$35ae047d$SATQ$, $SATQ$f0c9e8fd-3545-4ef8-8b86-366565650b78$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 1929, Edwin Herbert Land invented a polarizing filter that was featured in a number of products, from sunglasses to 3D movies. A decade later, Land <span aria-hidden="true">______</span><span class="sr-only">blank</span> his technology to invent the world&rsquo;s first instant camera, the Polaroid Land camera.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"059d0002-57d9-4788-81ff-e5ffc5240221","content":"<p>used</p>"},{"id":"efb8c020-c6a0-4c05-9846-7abdff49a82f","content":"<p>to have used</p>"},{"id":"dd9bc569-1d53-483c-82dd-334666d63c5f","content":"<p>to use</p>"},{"id":"4e1aa358-8f23-49f5-9cc3-6c1f2acffa92","content":"<p>using</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["059d0002-57d9-4788-81ff-e5ffc5240221"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject (in this case, Land), and this choice supplies the finite past tense verb "used" to indicate what Land did with the technology he had invented.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite perfect infinitive "to have used" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive "to use" doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite participle "using" doesn&rsquo;t supply the main clause with a finite verb.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"35ae047d","external_id":"f0c9e8fd-3545-4ef8-8b86-366565650b78","vaultid":null,"uId":"3297c046-b1da-4b02-ba7e-719b3eafe56b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 1929, Edwin Herbert Land invented a polarizing filter that was featured in a number of products, from sunglasses to 3D movies. A decade later, Land <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> his technology to invent the world&rsquo;s first instant camera, the Polaroid Land camera.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"059d0002-57d9-4788-81ff-e5ffc5240221","content":"<p>used</p>"},{"id":"efb8c020-c6a0-4c05-9846-7abdff49a82f","content":"<p>to have used</p>"},{"id":"dd9bc569-1d53-483c-82dd-334666d63c5f","content":"<p>to use</p>"},{"id":"4e1aa358-8f23-49f5-9cc3-6c1f2acffa92","content":"<p>using</p>"}],"keys":["059d0002-57d9-4788-81ff-e5ffc5240221"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject (in this case, Land), and this choice supplies the finite past tense verb \"used\" to indicate what Land did with the technology he had invented.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite perfect infinitive \"to have used\" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive \"to use\" doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite participle \"using\" doesn&rsquo;t supply the main clause with a finite verb.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$36868920$SATQ$, $SATQ$aa494bb3-a442-4bba-9a94-622b0297b91b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Increasing the heat on an uncovered boiling pot of water does not increase the temperature of the water. What increases is the rate at which the water turns to <span aria-hidden="true">______</span><span class="sr-only">blank</span> a pressure cooker pot, though, an airtight seal traps the vapor in the pot, creating pressure that allows the temperature of the water to increase past its boiling point.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"9a837a5b-6cbe-41d6-bd68-dcfd92e856fa","content":"<p>vapor<span data-ssml-say-as=\"characters\">.</span> With</p>"},{"id":"7a92e804-cd56-4c5f-bc33-8f2da10559fd","content":"<p>vapor with</p>"},{"id":"3e08e814-6b16-4b00-9043-41e69b703b5a","content":"<p>vapor<span data-ssml-say-as=\"characters\">,</span> with</p>"},{"id":"5a72c30f-5394-4a65-85c7-8080968a5013","content":"<p>vapor and with</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["9a837a5b-6cbe-41d6-bd68-dcfd92e856fa"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence ("What&hellip;vapor") and another ("With&hellip;point").</p><p>Choice B is incorrect because it results in a run-on sentence. The sentences ("What&hellip;vapor" and "with&hellip;point") are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction "and" can&rsquo;t be used in this way to join sentences.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"36868920","external_id":"aa494bb3-a442-4bba-9a94-622b0297b91b","vaultid":null,"uId":"7b054d04-3e1f-4ae2-a7e0-e50fa0999d9d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Increasing the heat on an uncovered boiling pot of water does not increase the temperature of the water. What increases is the rate at which the water turns to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a pressure cooker pot, though, an airtight seal traps the vapor in the pot, creating pressure that allows the temperature of the water to increase past its boiling point.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"9a837a5b-6cbe-41d6-bd68-dcfd92e856fa","content":"<p>vapor<span data-ssml-say-as=\"characters\">.</span> With</p>"},{"id":"7a92e804-cd56-4c5f-bc33-8f2da10559fd","content":"<p>vapor with</p>"},{"id":"3e08e814-6b16-4b00-9043-41e69b703b5a","content":"<p>vapor<span data-ssml-say-as=\"characters\">,</span> with</p>"},{"id":"5a72c30f-5394-4a65-85c7-8080968a5013","content":"<p>vapor and with</p>"}],"keys":["9a837a5b-6cbe-41d6-bd68-dcfd92e856fa"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (\"What&hellip;vapor\") and another (\"With&hellip;point\").</p><p>Choice B is incorrect because it results in a run-on sentence. The sentences (\"What&hellip;vapor\" and \"with&hellip;point\") are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction \"and\" can&rsquo;t be used in this way to join sentences.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669212,"updateDate":1743430669212}$SATQ$::jsonb, 1743430669212, 1743430669212),
    ($SATQ$36944347$SATQ$, $SATQ$b3bc2c6c-72fa-4157-ba24-5cee04bde61f$SATQ$::uuid, $SATQ$39107251-89f9-42cc-aa2a-e5d94dc078c9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Official measurements of the Mississippi River&rsquo;s length vary: according to the US Geologic Survey, the river is 2,300 miles long, whereas the Environmental Protection Agency records its length as 2,320 miles. This disparity can be explained in part by the fact that rivers such as the Mississippi expand and contract as <span aria-hidden="true">______</span><span class="sr-only">blank</span> sediment.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"cf7f0f51-f51b-42f4-89cf-bfa8554f9fb5","content":"<p>they accumulate</p>"},{"id":"5b44d43b-9f66-4676-8ecd-085ddfa8820d","content":"<p>one accumulates</p>"},{"id":"91e5c35b-e509-4ab5-a7d2-17609de747d4","content":"<p>it accumulates</p>"},{"id":"6c842b73-7f86-4959-9a49-e3041d72cc58","content":"<p>we accumulate</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["cf7f0f51-f51b-42f4-89cf-bfa8554f9fb5"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The noun that goes with "expand and contract" is "rivers," a plural noun. "They" is a third-person plural pronoun, so it can correctly stand in for "rivers."</p><p>Choice B is incorrect. This choice creates a pronoun-antecedent agreement error. "One" is a singular pronoun, but the noun that goes with "expand and contract" is "rivers," a plural noun. Choice C is incorrect. This choice creates a pronoun-antecedent agreement error. "It" is a singular pronoun, but the noun that goes with "expand and contract" is "rivers," a plural noun. Choice D is incorrect. This choice creates a pronoun-antecedent agreement error. The noun that goes with "expand and contract" is the plural noun "rivers." Rivers are not people, so "we" can&rsquo;t be used to stand in for it.</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-M001$SATQ$, $SATQ$$SATQ$, $SATQ$95af2aa5-23b9-4ef5-b7f0-1be4ff88130b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"36944347","external_id":"b3bc2c6c-72fa-4157-ba24-5cee04bde61f","vaultid":"39107251-89f9-42cc-aa2a-e5d94dc078c9","uId":"8e66913f-0e57-40e5-8311-18150f236790","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Official measurements of the Mississippi River&rsquo;s length vary: according to the US Geologic Survey, the river is 2,300 miles long, whereas the Environmental Protection Agency records its length as 2,320 miles. This disparity can be explained in part by the fact that rivers such as the Mississippi expand and contract as <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> sediment.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"cf7f0f51-f51b-42f4-89cf-bfa8554f9fb5","content":"<p>they accumulate</p>"},{"id":"5b44d43b-9f66-4676-8ecd-085ddfa8820d","content":"<p>one accumulates</p>"},{"id":"91e5c35b-e509-4ab5-a7d2-17609de747d4","content":"<p>it accumulates</p>"},{"id":"6c842b73-7f86-4959-9a49-e3041d72cc58","content":"<p>we accumulate</p>"}],"keys":["cf7f0f51-f51b-42f4-89cf-bfa8554f9fb5"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The noun that goes with \"expand and contract\" is \"rivers,\" a plural noun. \"They\" is a third-person plural pronoun, so it can correctly stand in for \"rivers.\"</p><p>Choice B is incorrect. This choice creates a pronoun-antecedent agreement error. \"One\" is a singular pronoun, but the noun that goes with \"expand and contract\" is \"rivers,\" a plural noun. Choice C is incorrect. This choice creates a pronoun-antecedent agreement error. \"It\" is a singular pronoun, but the noun that goes with \"expand and contract\" is \"rivers,\" a plural noun. Choice D is incorrect. This choice creates a pronoun-antecedent agreement error. The noun that goes with \"expand and contract\" is the plural noun \"rivers.\" Rivers are not people, so \"we\" can&rsquo;t be used to stand in for it.</p>","parenttemplatename":"OSP-KA-FSS-M001","parenttemplateid":"","templateclusterid":"95af2aa5-23b9-4ef5-b7f0-1be4ff88130b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$37e5c794$SATQ$, $SATQ$014a9604-e171-4d08-bf30-8e902eb9d335$SATQ$::uuid, $SATQ$2e3bc89f-39fe-48c8-8823-63d42c8bfc1b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Despite being cheap, versatile, and easy to produce, <span aria-hidden="true">______</span><span class="sr-only">blank</span> they are made from nonrenewable petroleum, and most do not biodegrade in landfills.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"2e22bef7-8909-4080-9ecd-4798383655a1","content":"<p>there are two problems associated with commercial plastics:</p>"},{"id":"5b6dd2e0-2309-481e-aa2d-271222171257","content":"<p>two problems are associated with commercial plastics:</p>"},{"id":"26884504-cc22-423d-bfe7-5ad4769e08de","content":"<p>commercial plastics&rsquo; two associated problems are that</p>"},{"id":"27553825-7225-4016-8b36-867104ece2a3","content":"<p>commercial plastics have two associated problems:</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["27553825-7225-4016-8b36-867104ece2a3"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice ensures that the modifying phrase &ldquo;despite being cheap, versatile, and easy to produce&rdquo; appears immediately before the noun it modifies, &ldquo;commercial plastics,&rdquo; clearly establishing that the commercial plastics&mdash;and not another noun in the sentence&mdash;are being described as cheap, versatile, and easy to produce.&nbsp;</p><p>Choice A is incorrect because it results in a dangling modifier. The placement of the function word &ldquo;there&rdquo; immediately after the modifying phrase illogically and confusingly suggests that &ldquo;there&rdquo; is cheap, versatile, and easy to produce. Choice B is incorrect because it results in a dangling modifier. The placement of the noun &ldquo;two problems&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;problems&rdquo; are cheap, versatile, and easy to produce. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;commercial plastics&rsquo; two associated problems&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;problems&rdquo; are cheap, versatile, and easy to produce. </p>$SATQ$, false, 0, $SATQ$OSP-632-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$707bcaa3-5c9f-446a-861f-689a9b239650$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"37e5c794","external_id":"014a9604-e171-4d08-bf30-8e902eb9d335","vaultid":"2e3bc89f-39fe-48c8-8823-63d42c8bfc1b","uId":"01fbd410-8032-44cd-9fa8-85db8ef0a17e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Despite being cheap, versatile, and easy to produce, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they are made from nonrenewable petroleum, and most do not biodegrade in landfills.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"2e22bef7-8909-4080-9ecd-4798383655a1","content":"<p>there are two problems associated with commercial plastics:</p>"},{"id":"5b6dd2e0-2309-481e-aa2d-271222171257","content":"<p>two problems are associated with commercial plastics:</p>"},{"id":"26884504-cc22-423d-bfe7-5ad4769e08de","content":"<p>commercial plastics&rsquo; two associated problems are that</p>"},{"id":"27553825-7225-4016-8b36-867104ece2a3","content":"<p>commercial plastics have two associated problems:</p>"}],"keys":["27553825-7225-4016-8b36-867104ece2a3"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice ensures that the modifying phrase &ldquo;despite being cheap, versatile, and easy to produce&rdquo; appears immediately before the noun it modifies, &ldquo;commercial plastics,&rdquo; clearly establishing that the commercial plastics&mdash;and not another noun in the sentence&mdash;are being described as cheap, versatile, and easy to produce.&nbsp;</p><p>Choice A is incorrect because it results in a dangling modifier. The placement of the function word &ldquo;there&rdquo; immediately after the modifying phrase illogically and confusingly suggests that &ldquo;there&rdquo; is cheap, versatile, and easy to produce. Choice B is incorrect because it results in a dangling modifier. The placement of the noun &ldquo;two problems&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;problems&rdquo; are cheap, versatile, and easy to produce. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;commercial plastics&rsquo; two associated problems&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;problems&rdquo; are cheap, versatile, and easy to produce. </p>","parenttemplatename":"OSP-632-SEC","parenttemplateid":"","templateclusterid":"707bcaa3-5c9f-446a-861f-689a9b239650","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$39ac6498$SATQ$, $SATQ$cae5bb9d-a3a6-4aa6-8a22-4abcde006444$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In forecasting weather events, meteorologists sometimes discuss the role of atmospheric rivers. What are atmospheric rivers, and how <span aria-hidden="true">______</span><span class="sr-only">blank</span> Part of the water cycle, atmospheric rivers are narrow channels of moisture moving through the atmosphere. In certain conditions, these &ldquo;rivers&rdquo; can release some of their moisture as precipitation.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7c8df3a6-f489-451e-a9bb-849a268b8f79","content":"<p>do they affect our weather.</p>"},{"id":"11d937e6-c64a-48eb-8c64-273c78798857","content":"<p>they do affect our weather.</p>"},{"id":"5cbaffab-f8fb-47c8-a3d9-1891a2e82355","content":"<p>do they affect our weather?</p>"},{"id":"b6d36417-a428-4b97-b2be-d485dd158f7a","content":"<p>they do affect our weather?</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["5cbaffab-f8fb-47c8-a3d9-1891a2e82355"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a question mark to punctuate the coordinated interrogative clauses "What are atmospheric rivers" and "how do they affect our weather," both of which ask direct questions.</p><p>Choice A is incorrect because a period can&rsquo;t be used in this way to punctuate an interrogative clause, such as "how do they affect our weather," at the end of a sentence. Choice B is incorrect because the structure requires an interrogative clause and a question mark at the end of the sentence. Choice D is incorrect because the structure requires an interrogative clause at the end of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"39ac6498","external_id":"cae5bb9d-a3a6-4aa6-8a22-4abcde006444","vaultid":null,"uId":"d6119be3-2756-469f-a956-62987c80d02d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In forecasting weather events, meteorologists sometimes discuss the role of atmospheric rivers. What are atmospheric rivers, and how <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Part of the water cycle, atmospheric rivers are narrow channels of moisture moving through the atmosphere. In certain conditions, these &ldquo;rivers&rdquo; can release some of their moisture as precipitation.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7c8df3a6-f489-451e-a9bb-849a268b8f79","content":"<p>do they affect our weather.</p>"},{"id":"11d937e6-c64a-48eb-8c64-273c78798857","content":"<p>they do affect our weather.</p>"},{"id":"5cbaffab-f8fb-47c8-a3d9-1891a2e82355","content":"<p>do they affect our weather?</p>"},{"id":"b6d36417-a428-4b97-b2be-d485dd158f7a","content":"<p>they do affect our weather?</p>"}],"keys":["5cbaffab-f8fb-47c8-a3d9-1891a2e82355"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a question mark to punctuate the coordinated interrogative clauses \"What are atmospheric rivers\" and \"how do they affect our weather,\" both of which ask direct questions.</p><p>Choice A is incorrect because a period can&rsquo;t be used in this way to punctuate an interrogative clause, such as \"how do they affect our weather,\" at the end of a sentence. Choice B is incorrect because the structure requires an interrogative clause and a question mark at the end of the sentence. Choice D is incorrect because the structure requires an interrogative clause at the end of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323049,"updateDate":1730147323049}$SATQ$::jsonb, 1730147323049, 1730147323049),
    ($SATQ$3a1239d2$SATQ$, $SATQ$56878c2f-bb61-4e08-91cf-80b1d17b0ac0$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>If an animal can recognize itself in a reflective surface (&ldquo;the mirror test&rdquo;), it is considered to have self-awareness. In a recent study, scientists <span aria-hidden="true">______</span><span class="sr-only">blank</span> for evidence of self-awareness in snakes, species that rely primarily on olfactory rather than visual processing, adapted the test to foreground smell, modifying the scent trails of North American eastern garter snakes and African ball pythons.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"75c51029-c087-4059-b801-b75557e81fea","content":"<p>searched</p>"},{"id":"9f9b144b-869e-445f-b051-bef14c595bf5","content":"<p>searching</p>"},{"id":"90506243-93f3-44a6-988b-e68806200271","content":"<p>were searching</p>"},{"id":"5fe9ab42-f82d-4b06-b843-7b017b4363de","content":"<p>have searched</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["9f9b144b-869e-445f-b051-bef14c595bf5"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle &ldquo;searching&rdquo; is correctly used to form a supplementary element that modifies the subject &ldquo;scientists,&rdquo; indicating that the scientists who adapted the test were looking for evidence of self-awareness in snakes.</p><p>Choice A is incorrect because it results in an ungrammatical sentence. The finite past tense verb &ldquo;searched&rdquo; can&rsquo;t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for. Choice C is incorrect because it results in an ungrammatical sentence. The finite past progressive verb &ldquo;were searching&rdquo; can&rsquo;t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for. Choice D is incorrect because it results in an ungrammatical sentence. The finite present perfect verb &ldquo;have searched&rdquo; can&rsquo;t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3a1239d2","external_id":"56878c2f-bb61-4e08-91cf-80b1d17b0ac0","vaultid":null,"uId":"04c2790c-0a79-4409-83ea-a711b6e6eba8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>If an animal can recognize itself in a reflective surface (&ldquo;the mirror test&rdquo;), it is considered to have self-awareness. In a recent study, scientists <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> for evidence of self-awareness in snakes, species that rely primarily on olfactory rather than visual processing, adapted the test to foreground smell, modifying the scent trails of North American eastern garter snakes and African ball pythons.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"75c51029-c087-4059-b801-b75557e81fea","content":"<p>searched</p>"},{"id":"9f9b144b-869e-445f-b051-bef14c595bf5","content":"<p>searching</p>"},{"id":"90506243-93f3-44a6-988b-e68806200271","content":"<p>were searching</p>"},{"id":"5fe9ab42-f82d-4b06-b843-7b017b4363de","content":"<p>have searched</p>"}],"keys":["9f9b144b-869e-445f-b051-bef14c595bf5"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle &ldquo;searching&rdquo; is correctly used to form a supplementary element that modifies the subject &ldquo;scientists,&rdquo; indicating that the scientists who adapted the test were looking for evidence of self-awareness in snakes.</p><p>Choice A is incorrect because it results in an ungrammatical sentence. The finite past tense verb &ldquo;searched&rdquo; can&rsquo;t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for. Choice C is incorrect because it results in an ungrammatical sentence. The finite past progressive verb &ldquo;were searching&rdquo; can&rsquo;t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for. Choice D is incorrect because it results in an ungrammatical sentence. The finite present perfect verb &ldquo;have searched&rdquo; can&rsquo;t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$3a2d77d7$SATQ$, $SATQ$86a457d1-ec67-4057-85fc-50dbbcaeb40d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In the 1950s, novel audio technologies allowed the addition of another instrument to jazz and swing <span aria-hidden="true">______</span><span class="sr-only">blank</span> relatively quiet instrument, its full range of sound was finally audible alongside the blaring brass instruments of the time, allowing flautists like Bennie Maupin and Bobbi Humphrey to perform with other jazz greats.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"2a69975a-b0bb-4f9e-ac39-d388866882f9","content":"<p>music, the flute, a</p>"},{"id":"161c3691-272e-4374-8fc0-4a0a1a219775","content":"<p>music. The flute, a</p>"},{"id":"f8e9ef14-61ac-4cd1-9d84-fc1ffe9fd682","content":"<p>music; the flute, a</p>"},{"id":"24b87d4a-a9a0-45a1-b46f-d250a065ed19","content":"<p>music: the flute. A</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["24b87d4a-a9a0-45a1-b46f-d250a065ed19"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of punctuation within and between sentences. In this choice, the colon correctly introduces the name of the instrument (the flute) that novel audio technologies allowed to be added to jazz and swing. In addition, the period is used to correctly mark the boundary between one sentence ("In&hellip;flute") and another ("A relatively&hellip;greats").</p><p>Choice A is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses ("In&hellip;quiet instrument" and "its&hellip;greats"). Choice B is incorrect. In standard English, it&rsquo;s unconventional to form a sentence in this way with two uncoordinated subjects ("the flute" and "its full range of sound"), and the lack of a clear main subject results in an awkwardly constructed and confusing sentence. Choice C is incorrect. In standard English, it&rsquo;s unconventional to form an independent clause in this way with two uncoordinated subjects ("the flute" and "its full range of sound"), and the lack of a clear main subject results in an awkwardly constructed and confusing clause.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3a2d77d7","external_id":"86a457d1-ec67-4057-85fc-50dbbcaeb40d","vaultid":null,"uId":"2b32c805-63ca-4ae0-8ff5-98d6038e4be4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In the 1950s, novel audio technologies allowed the addition of another instrument to jazz and swing <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> relatively quiet instrument, its full range of sound was finally audible alongside the blaring brass instruments of the time, allowing flautists like Bennie Maupin and Bobbi Humphrey to perform with other jazz greats.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"2a69975a-b0bb-4f9e-ac39-d388866882f9","content":"<p>music, the flute, a</p>"},{"id":"161c3691-272e-4374-8fc0-4a0a1a219775","content":"<p>music. The flute, a</p>"},{"id":"f8e9ef14-61ac-4cd1-9d84-fc1ffe9fd682","content":"<p>music; the flute, a</p>"},{"id":"24b87d4a-a9a0-45a1-b46f-d250a065ed19","content":"<p>music: the flute. A</p>"}],"keys":["24b87d4a-a9a0-45a1-b46f-d250a065ed19"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of punctuation within and between sentences. In this choice, the colon correctly introduces the name of the instrument (the flute) that novel audio technologies allowed to be added to jazz and swing. In addition, the period is used to correctly mark the boundary between one sentence (\"In&hellip;flute\") and another (\"A relatively&hellip;greats\").</p><p>Choice A is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses (\"In&hellip;quiet instrument\" and \"its&hellip;greats\"). Choice B is incorrect. In standard English, it&rsquo;s unconventional to form a sentence in this way with two uncoordinated subjects (\"the flute\" and \"its full range of sound\"), and the lack of a clear main subject results in an awkwardly constructed and confusing sentence. Choice C is incorrect. In standard English, it&rsquo;s unconventional to form an independent clause in this way with two uncoordinated subjects (\"the flute\" and \"its full range of sound\"), and the lack of a clear main subject results in an awkwardly constructed and confusing clause.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$3a35ddd1$SATQ$, $SATQ$a6122f55-b5d2-48a9-a947-ffe0fe9c2d0e$SATQ$::uuid, $SATQ$7cd56aab-21cf-4b54-96c0-3cc18f8723ae$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Like other amphibians, the wood frog (<em>Rana sylvatica</em>) is unable to generate its own heat, so during periods of subfreezing temperatures, it <span aria-hidden="true">______</span><span class="sr-only">blank</span> by producing large amounts of glucose, a sugar that helps prevent damaging ice from forming inside its cells.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"e17ee63c-ecb4-43f5-a5e1-434ff2332559","content":"<p>had survived</p>"},{"id":"5d8c9d3e-43c3-4884-9831-8a72e53856c2","content":"<p>survived</p>"},{"id":"36bb31b0-1e45-4f62-a38d-d9ba4e622c26","content":"<p>would survive</p>"},{"id":"7d88025b-01d9-406a-ac5b-e3c74fda8434","content":"<p>survives</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["7d88025b-01d9-406a-ac5b-e3c74fda8434"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb &ldquo;survives&rdquo; correctly indicates that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. </p><p>Choice A is incorrect because the past perfect verb &ldquo;had survived&rdquo; doesn&rsquo;t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. Choice B is incorrect because the past tense verb &ldquo;survived&rdquo; doesn&rsquo;t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. Choice C is incorrect because the conditional verb &ldquo;would survive&rdquo; doesn&rsquo;t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. </p>$SATQ$, false, 0, $SATQ$OSP-666-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$ac9532d6-81eb-4604-9884-289a5ca3554a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3a35ddd1","external_id":"a6122f55-b5d2-48a9-a947-ffe0fe9c2d0e","vaultid":"7cd56aab-21cf-4b54-96c0-3cc18f8723ae","uId":"43116a2d-5b51-46e5-95e1-7a52b19860cd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Like other amphibians, the wood frog (<em>Rana sylvatica</em>) is unable to generate its own heat, so during periods of subfreezing temperatures, it <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> by producing large amounts of glucose, a sugar that helps prevent damaging ice from forming inside its cells.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"e17ee63c-ecb4-43f5-a5e1-434ff2332559","content":"<p>had survived</p>"},{"id":"5d8c9d3e-43c3-4884-9831-8a72e53856c2","content":"<p>survived</p>"},{"id":"36bb31b0-1e45-4f62-a38d-d9ba4e622c26","content":"<p>would survive</p>"},{"id":"7d88025b-01d9-406a-ac5b-e3c74fda8434","content":"<p>survives</p>"}],"keys":["7d88025b-01d9-406a-ac5b-e3c74fda8434"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb &ldquo;survives&rdquo; correctly indicates that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. </p><p>Choice A is incorrect because the past perfect verb &ldquo;had survived&rdquo; doesn&rsquo;t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. Choice B is incorrect because the past tense verb &ldquo;survived&rdquo; doesn&rsquo;t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. Choice C is incorrect because the conditional verb &ldquo;would survive&rdquo; doesn&rsquo;t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. </p>","parenttemplatename":"OSP-666-SEC","parenttemplateid":"","templateclusterid":"ac9532d6-81eb-4604-9884-289a5ca3554a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959345,"updateDate":1691007959345}$SATQ$::jsonb, 1691007959345, 1691007959345),
    ($SATQ$3bceeb93$SATQ$, $SATQ$9c5279c5-530c-4758-a44e-cb3bc941f2e0$SATQ$::uuid, $SATQ$99a60673-1461-400e-9027-5d619e4005c3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>When they were first discovered in Australia in 1798, duck-billed, beaver-tailed platypuses so defied categorization that one scientist assigned them the name <em>Ornithorhynchus</em><em> </em><em>paradoxus</em>: &ldquo;paradoxical bird-snout.&rdquo; The animal,<em> </em>which lays eggs but also nurses <span aria-hidden="true">______</span><span class="sr-only">blank</span> young with milk, has since been classified as belonging to the monotremes group.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"df2239c6-1ead-4b36-9c5b-b7bf61867b7e","content":"<p>they&rsquo;re</p>"},{"id":"728c4507-b214-4cf8-958f-f62f7e1d8c6d","content":"<p>their</p>"},{"id":"09c7e0d7-ff57-4855-812e-fbbe4958bcb5","content":"<p>its</p>"},{"id":"2d923f09-4fa9-49df-a4da-f3bb5d90dafa","content":"<p>it&rsquo;s</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["09c7e0d7-ff57-4855-812e-fbbe4958bcb5"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The singular possessive pronoun "its" agrees with the singular antecedent "the animal" and indicates that the "young" belong to it.</p><p>Choice A is incorrect. This choice creates a pronoun-antecedent agreement error. "They&rsquo;re" is a contraction of "they are," a plural pronoun and verb, but the antecedent "the animal" is singular. Also, we don&rsquo;t need the extra verb "are" &mdash; we already have a main verb in this clause, so adding "are" would be confusing and ungrammatical. Choice B is incorrect. This choice creates a pronoun-antecedent agreement error. "Their" is a plural pronoun, but the subject of the sentence is "the animal," a singular noun. Choice D is incorrect. This choice creates a confusing and ungrammatical sentence. "It&rsquo;s" is a contraction for "it is." We already have the verb "nurses" in this clause, so we shouldn&rsquo;t add the verb "is."</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-H004$SATQ$, $SATQ$$SATQ$, $SATQ$309dc4fe-f605-49ab-b137-b5a284693fef$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3bceeb93","external_id":"9c5279c5-530c-4758-a44e-cb3bc941f2e0","vaultid":"99a60673-1461-400e-9027-5d619e4005c3","uId":"506606cc-faed-405f-bb8b-4e96c1f43135","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>When they were first discovered in Australia in 1798, duck-billed, beaver-tailed platypuses so defied categorization that one scientist assigned them the name <em>Ornithorhynchus</em><em> </em><em>paradoxus</em>: &ldquo;paradoxical bird-snout.&rdquo; The animal,<em> </em>which lays eggs but also nurses <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> young with milk, has since been classified as belonging to the monotremes group.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"df2239c6-1ead-4b36-9c5b-b7bf61867b7e","content":"<p>they&rsquo;re</p>"},{"id":"728c4507-b214-4cf8-958f-f62f7e1d8c6d","content":"<p>their</p>"},{"id":"09c7e0d7-ff57-4855-812e-fbbe4958bcb5","content":"<p>its</p>"},{"id":"2d923f09-4fa9-49df-a4da-f3bb5d90dafa","content":"<p>it&rsquo;s</p>"}],"keys":["09c7e0d7-ff57-4855-812e-fbbe4958bcb5"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The singular possessive pronoun \"its\" agrees with the singular antecedent \"the animal\" and indicates that the \"young\" belong to it.</p><p>Choice A is incorrect. This choice creates a pronoun-antecedent agreement error. \"They&rsquo;re\" is a contraction of \"they are,\" a plural pronoun and verb, but the antecedent \"the animal\" is singular. Also, we don&rsquo;t need the extra verb \"are\" &mdash; we already have a main verb in this clause, so adding \"are\" would be confusing and ungrammatical. Choice B is incorrect. This choice creates a pronoun-antecedent agreement error. \"Their\" is a plural pronoun, but the subject of the sentence is \"the animal,\" a singular noun. Choice D is incorrect. This choice creates a confusing and ungrammatical sentence. \"It&rsquo;s\" is a contraction for \"it is.\" We already have the verb \"nurses\" in this clause, so we shouldn&rsquo;t add the verb \"is.\"</p>","parenttemplatename":"OSP-KA-FSS-H004","parenttemplateid":"","templateclusterid":"309dc4fe-f605-49ab-b137-b5a284693fef","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$3daf126e$SATQ$, $SATQ$a333fdea-60c1-4c8b-90a3-80312913666e$SATQ$::uuid, $SATQ$284b1fbc-67a9-49b6-b8f5-aa79378a357a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>A model created by biologist Luis Valente predicts that the rate of speciation&mdash;the rate at which new species form&mdash;on an isolated island located approximately 5,000 kilometers from the nearest mainland <span aria-hidden="true">______</span><span class="sr-only">blank</span> triple the rate of speciation on an island only 500 kilometers from the mainland.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"65e5f89a-a68b-4c8d-b363-c6786e3bb871","content":"<p>being</p>"},{"id":"795ae47e-8caf-47c3-bb62-ee7165b1bcb5","content":"<p>to be</p>"},{"id":"c82fb42b-9942-4736-bd12-bef2f3f50fa7","content":"<p>to have been</p>"},{"id":"ae896360-fd87-4ad2-9d98-b8e3bec24bd7","content":"<p>will be</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["ae896360-fd87-4ad2-9d98-b8e3bec24bd7"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. Relative clauses, such as the one beginning with &ldquo;that,&rdquo; require a finite verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite future tense verb &ldquo;will be.&rdquo;&nbsp;</p><p>Choice A is incorrect because the nonfinite participle &ldquo;being&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice B is incorrect because the nonfinite to-infinitive &ldquo;to be&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice C is incorrect because the nonfinite to-infinitive &ldquo;to have been&rdquo; doesn&rsquo;t supply the clause with a finite verb. </p>$SATQ$, false, 0, $SATQ$OSP-668-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$3706dca8-f7db-44be-bcb5-108737a73026$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3daf126e","external_id":"a333fdea-60c1-4c8b-90a3-80312913666e","vaultid":"284b1fbc-67a9-49b6-b8f5-aa79378a357a","uId":"e5c7cf3d-4739-4d26-a02a-15a9ac5ced28","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>A model created by biologist Luis Valente predicts that the rate of speciation&mdash;the rate at which new species form&mdash;on an isolated island located approximately 5,000 kilometers from the nearest mainland <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> triple the rate of speciation on an island only 500 kilometers from the mainland.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"65e5f89a-a68b-4c8d-b363-c6786e3bb871","content":"<p>being</p>"},{"id":"795ae47e-8caf-47c3-bb62-ee7165b1bcb5","content":"<p>to be</p>"},{"id":"c82fb42b-9942-4736-bd12-bef2f3f50fa7","content":"<p>to have been</p>"},{"id":"ae896360-fd87-4ad2-9d98-b8e3bec24bd7","content":"<p>will be</p>"}],"keys":["ae896360-fd87-4ad2-9d98-b8e3bec24bd7"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. Relative clauses, such as the one beginning with &ldquo;that,&rdquo; require a finite verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite future tense verb &ldquo;will be.&rdquo;&nbsp;</p><p>Choice A is incorrect because the nonfinite participle &ldquo;being&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice B is incorrect because the nonfinite to-infinitive &ldquo;to be&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice C is incorrect because the nonfinite to-infinitive &ldquo;to have been&rdquo; doesn&rsquo;t supply the clause with a finite verb. </p>","parenttemplatename":"OSP-668-SEC","parenttemplateid":"","templateclusterid":"3706dca8-f7db-44be-bcb5-108737a73026","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959345,"updateDate":1691007959345}$SATQ$::jsonb, 1691007959345, 1691007959345),
    ($SATQ$3ed5ebb4$SATQ$, $SATQ$b26aaabd-9fc6-4b06-be2b-c5769258d1f3$SATQ$::uuid, $SATQ$5f8764d1-e9af-45a4-bcc7-7adb8a82bdab$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In her analysis of Edith Wharton&rsquo;s <em>The House of Mirth </em>(1905), scholar Candace Waid observes that the novel depicts the upper classes of New York society as &ldquo;consumed by the appetite of a soulless <span aria-hidden="true">______</span><span class="sr-only">blank</span> an apt assessment given that <em>The House of Mirth </em>is set during the Gilded Age, a period marked by rapid industrialization, economic greed, and widening wealth disparities.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"5d533a69-1ea6-4e38-8d0a-66b44c311cf4","content":"<p>materialism&rdquo;; and</p>"},{"id":"03bfc2c6-6a46-4080-8bae-133653c3461e","content":"<p>materialism&rdquo; and&nbsp;</p>"},{"id":"37408669-5170-4be5-966c-492cbd89bb15","content":"<p>materialism,&rdquo;</p>"},{"id":"4d34d256-97a6-4b48-9457-152df6af305e","content":"<p>materialism&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["37408669-5170-4be5-966c-492cbd89bb15"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation between a main clause and a supplementary noun phrase. This choice correctly uses a comma to mark the boundary between the main clause (&ldquo;scholar&hellip;materialism&rdquo;) and the supplementary noun phrase (&ldquo;an apt assessment&rdquo;) that describes Waid&rsquo;s observation about how <em>The House of Mirth</em> depicts the upper classes of New York society. </p><p>Choice A is incorrect because a semicolon and the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to mark the boundary between a main clause and a supplementary noun phrase. Choice B is incorrect. Joining the main clause (&ldquo;scholar&hellip;materialism&rdquo;) and the following noun phrase with the conjunction &ldquo;and&rdquo; results in a confusing and illogical sentence that suggests that the novel depicts the upper classes of New York society as &ldquo;an apt assessment,&rdquo; which doesn&rsquo;t make sense in this context. Choice D is incorrect because it fails to mark the boundary between the main clause and the supplementary noun phrase with appropriate punctuation. </p>$SATQ$, false, 0, $SATQ$OSP-693-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$319c6064-a285-4cfb-be11-7a5f7cce8f23$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3ed5ebb4","external_id":"b26aaabd-9fc6-4b06-be2b-c5769258d1f3","vaultid":"5f8764d1-e9af-45a4-bcc7-7adb8a82bdab","uId":"f9dcd6f7-591a-43b2-8a45-2735a3e49451","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In her analysis of Edith Wharton&rsquo;s <em>The House of Mirth </em>(1905), scholar Candace Waid observes that the novel depicts the upper classes of New York society as &ldquo;consumed by the appetite of a soulless <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> an apt assessment given that <em>The House of Mirth </em>is set during the Gilded Age, a period marked by rapid industrialization, economic greed, and widening wealth disparities.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"5d533a69-1ea6-4e38-8d0a-66b44c311cf4","content":"<p>materialism&rdquo;; and</p>"},{"id":"03bfc2c6-6a46-4080-8bae-133653c3461e","content":"<p>materialism&rdquo; and&nbsp;</p>"},{"id":"37408669-5170-4be5-966c-492cbd89bb15","content":"<p>materialism,&rdquo;</p>"},{"id":"4d34d256-97a6-4b48-9457-152df6af305e","content":"<p>materialism&rdquo;</p>"}],"keys":["37408669-5170-4be5-966c-492cbd89bb15"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation between a main clause and a supplementary noun phrase. This choice correctly uses a comma to mark the boundary between the main clause (&ldquo;scholar&hellip;materialism&rdquo;) and the supplementary noun phrase (&ldquo;an apt assessment&rdquo;) that describes Waid&rsquo;s observation about how <em>The House of Mirth</em> depicts the upper classes of New York society. </p><p>Choice A is incorrect because a semicolon and the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to mark the boundary between a main clause and a supplementary noun phrase. Choice B is incorrect. Joining the main clause (&ldquo;scholar&hellip;materialism&rdquo;) and the following noun phrase with the conjunction &ldquo;and&rdquo; results in a confusing and illogical sentence that suggests that the novel depicts the upper classes of New York society as &ldquo;an apt assessment,&rdquo; which doesn&rsquo;t make sense in this context. Choice D is incorrect because it fails to mark the boundary between the main clause and the supplementary noun phrase with appropriate punctuation. </p>","parenttemplatename":"OSP-693-SEC","parenttemplateid":"","templateclusterid":"319c6064-a285-4cfb-be11-7a5f7cce8f23","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$3fee46f2$SATQ$, $SATQ$7cdef224-4daf-47ec-bf14-b5559cb48809$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Sociologist Todd Gitlin co-opted the term &ldquo;recombinant,&rdquo; normally used in reference to genetic engineering, to describe serialized television shows of the 1980s. Gitlin&rsquo;s use of the term referenced TV studios&rsquo; practice of repackaging successful narrative formulas as new <span aria-hidden="true">______</span><span class="sr-only">blank</span> even shows that varied only slightly from other shows still attracted sizeable audiences.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"e0c256fa-4b9f-4604-8dfb-4bf958974782","content":"<p>content<span data-ssml-say-as=\"characters\">,</span> in that era</p>"},{"id":"6c5e9a52-8f58-4fb7-83c8-16bfe9a6f1fa","content":"<p>content<span data-ssml-say-as=\"characters\">;</span> in that era<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"d52e4671-a4e5-46be-8181-8c14d02645bf","content":"<p>content in that era<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"ce9141c6-db36-4d17-bcc1-7d99e9fdcb0c","content":"<p>content<span data-ssml-say-as=\"characters\">,</span> in that era<span data-ssml-say-as=\"characters\">,</span></p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["6c5e9a52-8f58-4fb7-83c8-16bfe9a6f1fa"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause ("Gitlin&rsquo;s&hellip;content") and the second main clause beginning with a supplementary phrase ("in&hellip;audiences"). Further, placing a comma after "era" separates the supplementary phrase "in that era" from the rest of the main clause that follows ("even&hellip;audiences").</p><p>Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Further, this choice fails to mark the boundary between the supplementary phrase "in that era" and the rest of the main clause that follows ("even&hellip;audiences"). Choice C is incorrect because it results in a run-on sentence. The two main clauses ("Gitlin&rsquo;s&hellip;content" and "in&hellip;audiences") are fused without punctuation and/or a conjunction. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3fee46f2","external_id":"7cdef224-4daf-47ec-bf14-b5559cb48809","vaultid":null,"uId":"d7f75f98-ef59-479f-881a-ae3eb475e1ae","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Sociologist Todd Gitlin co-opted the term &ldquo;recombinant,&rdquo; normally used in reference to genetic engineering, to describe serialized television shows of the 1980s. Gitlin&rsquo;s use of the term referenced TV studios&rsquo; practice of repackaging successful narrative formulas as new <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> even shows that varied only slightly from other shows still attracted sizeable audiences.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"e0c256fa-4b9f-4604-8dfb-4bf958974782","content":"<p>content<span data-ssml-say-as=\"characters\">,</span> in that era</p>"},{"id":"6c5e9a52-8f58-4fb7-83c8-16